# First aid: DRSABCD basic life support (ANZCOR). Run with _scripts/gen_sheets.py
fact("drsabcd",
 "DRSABCD: Basic Life Support and CPR Steps (Australia)",
 "DRSABCD explained: the Australian basic life support steps for an unresponsive person, how to do CPR on adults, children and babies, using a defibrillator, and choking.",
 "DRSABCD: Basic Life Support", "Basic life support (DRSABCD)",
 "DRSABCD is the Australian action plan for someone who has collapsed: Danger, Response, Send for help, Airway, Breathing, CPR, Defibrillation. You can’t make things worse. Any CPR is better than none, and the 000 call-taker will talk you through it.",
 '<p class="callout"><b>Unresponsive and not breathing normally? Call 000 now</b> (112 also works from a mobile). Put the phone on speaker, start CPR, and send someone for a defibrillator (AED).</p>' +
 h2("D: Danger", [
   "Check for danger to you, bystanders and the person: traffic, fire, electricity, water, sharps.",
   "Only move the person if it isn’t safe to help them where they are."]) +
 h2("R: Response", [
   "Talk and touch. Remember <b>COWS</b>: Can you hear me? Open your eyes. What’s your name? Squeeze my hand.",
   "Squeeze their shoulders firmly. Don’t shake a baby or anyone who may have a neck injury.",
   "If they respond, make them comfortable, check for injuries and get help if needed."]) +
 h2("S: Send for help", [
   "Call <b>000</b>, or ask a specific person to call: “You in the blue shirt, call 000.”",
   "Ask someone else to find the nearest AED. Many are listed in apps such as GoodSAM and on state AED registers."]) +
 h2("A: Airway", [
   "Open the mouth and look for anything blocking it, like food, vomit or blood.",
   "If something’s there, roll them onto their side and clear it with your fingers.",
   "Open the airway: one hand on the forehead, tilt the head back gently and lift the chin. For a baby, keep the head level (neutral), not tilted back."]) +
 h2("B: Breathing", [
   "Look, listen and feel for normal breathing for no more than 10 seconds.",
   "<b>Gasping or odd, noisy breaths are not normal breathing.</b> They are common in the first minutes of cardiac arrest. Start CPR.",
   "Breathing normally? Put them in the <b>recovery position</b> on their side, keep the airway open and keep checking until help arrives."]) +
 h2("C: CPR", [
   "Kneel beside them. Put the heel of one hand on the <b>lower half of the breastbone</b>, in the centre of the chest, and the other hand on top.",
   "Push down hard, <b>one third of the depth of the chest</b> (about 5 cm in an adult), and let it come right back up each time.",
   "Go fast: <b>100 to 120 a minute</b>. The beat of ‘Stayin’ Alive’ is about right.",
   "Give <b>30 compressions, then 2 breaths</b>: tilt the head, pinch the nose, seal your mouth over theirs and blow until the chest rises.",
   "Don’t want to give breaths, or can’t? Do <b>compressions only</b>, without stopping.",
   "Keep going. Swap with another rescuer every 2 minutes if you can, with as little pause as possible."]) +
 h2("D: Defibrillation", [
   "Turn on the AED as soon as it arrives and follow the voice prompts. Anyone can use one; you don’t need training.",
   "Stick the pads on the bare chest as shown on the pictures. Keep doing CPR while the pads go on.",
   "Stand clear when it analyses and shocks. Restart CPR straight away when it says to.",
   "An AED only shocks if the heart rhythm needs it. It can’t shock someone who doesn’t need it."]) +
 h2("Children and babies", [
   "The steps are the same, with the same 30 compressions to 2 breaths.",
   "<b>Children (1 year to puberty):</b> one or two hands on the lower half of the breastbone, one third of the chest depth.",
   "<b>Babies (under 1):</b> two fingers on the lower half of the breastbone, about 4 cm deep. Cover the mouth and nose with your mouth and give small puffs.",
   "Use child pads or a child setting on the AED if there is one. If not, adult pads are fine."]) +
 h2("When to stop CPR", [
   "The person starts breathing normally or moving.",
   "Paramedics or another trained person takes over.",
   "You’re too exhausted to keep going, or it becomes unsafe."]) +
 h2("Choking", [
   "Coughing? Encourage them to keep coughing and stay with them.",
   "Can’t cough, speak or breathe? Call 000. Give up to <b>5 firm back blows</b> between the shoulder blades, then up to <b>5 chest thrusts</b> (like CPR compressions, but sharper and slower) if it hasn’t cleared. Keep alternating.",
   "If they become unresponsive, start DRSABCD and CPR.",
   "Babies: lay them face down along your forearm, head lower, for back blows; then face up on your forearm for chest thrusts with two fingers."]) +
 h2("Good to know", [
   "Every minute without CPR or a shock cuts the chance of surviving a cardiac arrest by about 10%.",
   "In Australia, people who help in good faith in an emergency are legally protected.",
   "Broken ribs can happen with good CPR. They heal; a brain without oxygen doesn’t.",
   "A short CPR course takes a few hours and is worth redoing every year."]),
 [("What does DRSABCD stand for?", "Danger, Response, Send for help, Airway, Breathing, CPR and Defibrillation. It’s the basic life support action plan used in Australia and New Zealand."),
  ("What is the CPR ratio in Australia?", "30 chest compressions to 2 rescue breaths, for adults, children and babies, at 100 to 120 compressions a minute. If you can’t or won’t give breaths, continuous compressions are still worthwhile."),
  ("How deep should CPR compressions be?", "One third of the depth of the chest: about 5 cm for an adult, and about 4 cm for a baby. Let the chest come all the way back up between compressions."),
  ("Can I hurt someone by doing CPR?", "Someone who is unresponsive and not breathing normally has stopped their heart, so CPR can only help. Rib fractures can happen but they heal. You’re legally protected when you help in good faith."),
  ("Do I need training to use a defibrillator?", "No. Public AEDs talk you through every step and only shock if the heart needs it.")],
 [("Australian Resuscitation Council: guidelines and flowcharts", "https://www.resus.org.au/", "The official ANZCOR basic life support flowchart. Free."),
  ("healthdirect: How to do CPR", "https://www.healthdirect.gov.au/how-to-do-cpr", "Plain-English guide with diagrams. Free."),
  ("St John Ambulance Australia: first aid courses", "https://www.stjohn.org.au/", "CPR and first aid training across Australia.")],
 [("ANZCOR Guideline 8: Cardiopulmonary resuscitation", "https://www.anzcor.org/home/basic-life-support/guideline-8-cardiopulmonary-resuscitation-cpr/"),
  ("ANZCOR Guideline 7: Automated external defibrillation in basic life support", "https://www.anzcor.org/home/basic-life-support/guideline-7-automated-external-defibrillation-in-basic-life-support/"),
  ("ANZCOR Guideline 4: Airway (including choking)", "https://www.anzcor.org/home/basic-life-support/guideline-4-airway/"),
  ("ANZCOR Basic Life Support flowchart", "https://www.anzcor.org/home/basic-life-support/")],
 [("Anaphylaxis", "/anaphylaxis/"), ("Asthma", "/asthma/"), ("Heart failure", "/heart-failure/")],
 groups=["Other"], blurb="The Australian basic life support steps: Danger, Response, Send for help, Airway, Breathing, CPR, Defibrillation.",
 search="drsabcd cpr basic life support first aid resuscitation defibrillator aed choking compressions dr abc")
